-- Atlas (PRD 40): shared, permanent reference data. Countries and their typical
-- conditions are seeded here and refreshed by `pnpm --filter @trove/api atlas:sync`;
-- guides are stored permanently the first time they are read or synced.
-- CreateTable
CREATE TABLE "trove"."atlas_countries" (
    "country_code" VARCHAR(2) NOT NULL,
    "region" VARCHAR(16) NOT NULL,
    "wikivoyage_title" TEXT NOT NULL,
    "climate_city" TEXT NOT NULL,
    "latitude" DECIMAL(9,6) NOT NULL,
    "longitude" DECIMAL(9,6) NOT NULL,
    "climate" JSONB,
    "climate_year_from" SMALLINT,
    "climate_year_to" SMALLINT,
    "updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "atlas_countries_pkey" PRIMARY KEY ("country_code")
);

-- CreateTable
CREATE TABLE "trove"."atlas_guides" (
    "id" UUID NOT NULL,
    "country_code" VARCHAR(2) NOT NULL,
    "language" VARCHAR(8) NOT NULL DEFAULT 'en',
    "title" TEXT NOT NULL,
    "revision_id" BIGINT NOT NULL,
    "content" JSONB NOT NULL,
    "fetched_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "atlas_guides_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "atlas_guides_fetched_at_idx" ON "trove"."atlas_guides"("fetched_at");

-- CreateIndex
CREATE UNIQUE INDEX "atlas_guides_country_code_language_key" ON "trove"."atlas_guides"("country_code", "language");

-- AddForeignKey
ALTER TABLE "trove"."atlas_guides" ADD CONSTRAINT "atlas_guides_country_code_fkey" FOREIGN KEY ("country_code") REFERENCES "trove"."atlas_countries"("country_code") ON DELETE CASCADE ON UPDATE CASCADE;

-- Shared data still stays behind the API, matching the other Trove tables.
ALTER TABLE "trove"."atlas_countries" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON "trove"."atlas_countries" FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON "trove"."atlas_countries" FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON "trove"."atlas_countries" FROM authenticated;
  END IF;
END $$;
ALTER TABLE "trove"."atlas_guides" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON "trove"."atlas_guides" FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON "trove"."atlas_guides" FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON "trove"."atlas_guides" FROM authenticated;
  END IF;
END $$;

-- Seed: 200 countries, typical conditions 2021-2025 (Open-Meteo archive).
ON CONFLICT ("country_code") DO NOTHING;
